import React from "react";
import * as Yup from "yup";
// form
import { yupResolver } from "@hookform/resolvers/yup";
import { useForm } from "react-hook-form";
// components
import FormProvider, { RHFTextField } from "../../components/hook-form";
import { Button, Stack } from "@mui/material";
import { useDispatch, useSelector } from "react-redux";
import { VerifyEmail } from "../../redux/slices/auth";
import RHFCodes from "../../components/hook-form/RHFCodes";

// ----------------------------------------------------------------------

export default function VerifyForm() {
    const { email } = useSelector((state) => state.auth);
    const dispatch = useDispatch();
    const VerifyCodeSchema = Yup.object().shape({
        code1: Yup.string().required("Otp is required"),
        code2: Yup.string().required("Otp is required"),
        code3: Yup.string().required("Otp is required"),
        code4: Yup.string().required("Otp is required"),
        code5: Yup.string().required("Otp is required"),
        code6: Yup.string().required("Otp is required"),
    });

    const methods = useForm({
        mode: "onChange",
        resolver: yupResolver(VerifyCodeSchema),
        defaultValues: { code1: "", code2: "", code3: "", code4: "", code5: "", code6: "" },
    });

    const { reset, setError, handleSubmit, formState } = methods;

    const onSubmit = async (data) => {
        try {
            dispatch(VerifyEmail({
                otp:`${data.code1}${data.code2}${data.code3}${data.code4}${data.code5}${data.code6}`,
                email:email,
            }));
        } catch (error) {
            reset();
            setError("after Submit", {
                ...error,
                message: error.message,
            })
        }
    };

    return (
        <FormProvider methods={methods} onSubmit={handleSubmit(onSubmit)}>
            <Stack spacing={3}>
                <RHFCodes keyName="code" inputs={["code1", "code2", "code3", "code4", "code5", "code6"]} />


                <Button
                    // loading={isLoading}
                    fullWidth
                    size="large"
                    type="submit"
                    variant="contained"
                    sx={{
                        mt: 3,
                        bgcolor: "text.primary",
                        color: (theme) =>
                            theme.palette.mode === "light" ? "common.white" : "grey.800",
                        "&:hover": {
                            bgcolor: "text.primary",
                            color: (theme) =>
                                theme.palette.mode === "light" ? "common.white" : "grey.800",
                        },
                    }}
                >
                    Verify
                </Button>
            </Stack>
        </FormProvider>
    );
}